const body = ($input.first().json && $input.first().json.body) || $input.first().json || {};
// The amount can arrive as a number, as "11.17", or with a currency symbol in front. It is
// read the way a shopper's browser sends it, because an amount that parsed to 0 used to reach
// PayPal as an empty string and the payment died with a 400 INVALID_REQUEST.
const rawAmount = body.amount_usd !== undefined ? body.amount_usd : body.total_usd;
const cleanedAmount = String(rawAmount === undefined || rawAmount === null ? '' : rawAmount).replace(/[^0-9.]/g, '');
const amount = Number(cleanedAmount);
const slug = String(body.slug || '').trim();
const orderId = 'ORD-' + Date.now().toString(36).toUpperCase() + '-' + Math.floor(Math.random() * 900 + 100);

// THE MONEY THE BUYER SAW IS THE MONEY THAT IS CHARGED.
// The shop sends the amount already expressed in the currency it will be charged in, plus the
// amount in the shop's own shillings and the figure the buyer read on the page. PayPal only
// accepts a fixed list of currencies (the Ugandan shilling is NOT one of them - it answers
// CURRENCY_NOT_SUPPORTED), so the currency is validated here rather than passed through blindly.
const PAYPAL_CURRENCIES = ['USD','EUR','GBP','AUD','CAD','CHF','HKD','JPY','MXN','NZD','NOK','PHP','PLN','RUB','SEK','SGD','THB','TWD','CZK','DKK','HUF','ILS','MYR','BRL'];
const requested = String(body.currency || 'USD').toUpperCase();
const chargeCurrency = PAYPAL_CURRENCIES.indexOf(requested) >= 0 ? requested : 'USD';
const amountLocal = Number(String(body.amount_local === undefined ? '' : body.amount_local).replace(/[^0-9.]/g, '')) || 0;
const displayCurrency = String(body.display_currency || '').toUpperCase();
const displayAmount = String(body.display_amount || '');

if (!isFinite(amount) || amount <= 0 || !slug) {
  // No order is created and PayPal is never called, so nothing can be half-charged.
  return [{ json: { ok: false, order_failed: true, status: 'FAILED', error: 'A positive amount_usd and a slug are required.', amount_seen: String(rawAmount === undefined ? '' : rawAmount) } }];
}

return [{
  json: {
    ok: true,
    order_id: orderId,
    slug: slug,
    merchant_name: String(body.merchant_name || ''),
    buyer_phone: String(body.buyer_phone || '').replace(/[^0-9]/g, ''),
    buyer_name: String(body.buyer_name || 'Customer'),
    amount_usd: amount.toFixed(2),
    currency: chargeCurrency,
    amount_local: amountLocal.toFixed(2),
    display_currency: displayCurrency,
    display_amount: displayAmount,
    items_summary: String(body.items_summary || '').slice(0, 500)
  }
}];

