const prep = $('Prepare Checkout').first().json;
let paypal = {};
try { paypal = $('Create PayPal Order').first().json || {}; } catch (e) {}

let approveUrl = '';
const links = Array.isArray(paypal.links) ? paypal.links : [];
// An order that never got as far as PayPal carries its own reason; that reason is what the
// buyer and the page see.
const prepFailed = prep.ok === false;
const failureReason = prepFailed ? String(prep.error || 'The order could not be started.') : '';
for (const l of links) {
  if (l && (l.rel === 'approve' || l.rel === 'payer-action')) { approveUrl = l.href; break; }
}

return [{
  json: {
    ok: Boolean(approveUrl),
    order_id: prep.order_id,
    amount_usd: prep.amount_usd,
    currency: prep.currency,
    amount_local: prep.amount_local,
    display_currency: prep.display_currency,
    display_amount: prep.display_amount,
    paypal_order_id: paypal.id || '',
    approve_url: approveUrl,
    status: approveUrl ? 'AWAITING_APPROVAL' : 'FAILED',
    error: approveUrl ? '' : (failureReason || 'PayPal did not return an approval link.')
  }
}];

const NL = String.fromCharCode(10);
const order = $('Load Order For Capture').first().json || {};
// PayPal's own answer to the capture is what decides paid or not. It is read by node name: the
// node just upstream only returns the updated DB row, whose status is PAID/FAILED rather than
// PayPal's COMPLETED, and judging on that told a paying buyer their payment had failed.
let captured = {};
try { captured = $('Capture PayPal Payment').first().json || {}; } catch (e) { captured = {}; }

// A capture that PayPal says is already done counts as paid - the money did move, and telling
// the buyer it failed would be a lie.
const rawStatus = String(captured.status || '').toUpperCase();
const blob = String((captured.error && captured.error.issue) || (captured.error && captured.error.message) || captured.message || '').toUpperCase();
const paid = rawStatus === 'COMPLETED' || blob.indexOf('ALREADY_CAPTURED') >= 0;

const currency = String(order.currency || 'USD').toUpperCase();
const amount = Number(order.amount_usd || 0);
const charged = currency + ' ' + amount.toFixed(2);
const items = String(order.items_summary || '')
  .split(NL)
  .map(function (l) { return l.trim(); })
  .filter(function (l) { return l && l.indexOf('Cart items') !== 0 && l.indexOf('Total') !== 0; });

const lines = [];
if (paid) {
  lines.push('PAYMENT RECEIVED');
  lines.push('');
  lines.push('Order: ' + String(order.order_id || ''));
  if (items.length) {
    lines.push('');
    lines.push('Items:');
    for (const it of items) { lines.push(it); }
  }
  lines.push('');
  lines.push('Charged: ' + charged);
  lines.push('This was TEST MODE - no real money moved.');
  lines.push('');
  lines.push('Your order is confirmed and the seller has been notified.');
} else {
  lines.push('PAYMENT NOT COMPLETED');
  lines.push('');
  lines.push('Order: ' + String(order.order_id || ''));
  lines.push('No money was taken.');
  lines.push('Please try again, or choose Cash on Delivery.');
}

return [{ json: { paid: paid, message_text: lines.join(NL), recipient: String(order.buyer_phone || ''), order_id: String(order.order_id || '') } }];

