const body = ($input.first().json && $input.first().json.body) || $input.first().json || {};
const orderId = 'ORD-' + Date.now().toString(36).toUpperCase() + '-' + Math.floor(Math.random() * 900 + 100);
const digits = (v) => String(v === undefined || v === null ? '' : v).replace(/[^0-9]/g, '');
const amount = Number(String(body.amount_local === undefined ? '' : body.amount_local).replace(/[^0-9.]/g, '')) || 0;
const method = String(body.payment_method || 'CASH_ON_DELIVERY').toUpperCase();
const amountUsd = Number(String(body.amount_usd === undefined ? '' : body.amount_usd).replace(/[^0-9.]/g, '')) || 0;

// The merchant alert goes to the SHOP's own number the page sent, never to the buyer. A shopper
// often leaves the phone field empty, and a WhatsApp send with no recipient used to kill the
// whole order after it had already been written to the table.
const merchantPhone = digits(body.merchant_phone);
const buyerPhone = digits(body.buyer_phone);
const isMobile = method.indexOf('MOBILE') === 0;
const isCash = !isMobile && method !== 'CARD' && method !== 'PAYPAL';
const methodLabel = isMobile ? 'Mobile Money' : (isCash ? 'Pay on delivery (cash)' : 'Card / PayPal');
const itemsSummary = String(body.items_summary || '').slice(0, 500);
// The merchant reads ONE line per item, taken from the order the buyer just wrote, so the
// alert is a receipt rather than a bare amount: what to bring, and how it will be paid.
const receiptLines = itemsSummary
  .split(' | ')
  .map(function (part) { return String(part || '').trim(); })
  .filter(function (part) { return part && part.indexOf('Notes:') !== 0; })
  .map(function (part) { return part.charAt(0) === '-' ? part : '- ' + part; })
  .join(String.fromCharCode(10));

return [{
  json: {
    order_id: orderId,
    slug: String(body.slug || ''),
    merchant_name: String(body.merchant_name || ''),
    merchant_phone: merchantPhone,
    buyer_name: String(body.buyer_name || 'Customer'),
    buyer_phone: buyerPhone,
    has_buyer_phone: Boolean(buyerPhone),
    amount_local: amount,
    amount_display: 'UGX ' + amount.toLocaleString('en-US'),
    amount_usd: amountUsd > 0 ? amountUsd.toFixed(2) : '',
    currency: String(body.currency || 'UGX'),
    payment_method: method,
    method_label: methodLabel,
    is_cash: isCash,
    receipt_lines: receiptLines,
    items_summary: itemsSummary
  }
}];

