const body = ($input.first().json && $input.first().json.body) || $input.first().json || {};
const type = String(body.event_type || '');
const resource = body.resource || {};

// The PayPal order id is reachable from each of these events.
let paypalOrderId = '';
if (resource.supplementary_data && resource.supplementary_data.related_ids) {
  paypalOrderId = String(resource.supplementary_data.related_ids.order_id || '');
}
if (!paypalOrderId && resource.id && String(resource.id).indexOf('ORD-') !== 0 && type.indexOf('CHECKOUT.ORDER') === 0) {
  paypalOrderId = String(resource.id);
}
if (!paypalOrderId && resource.custom_id) paypalOrderId = String(resource.custom_id);

const paid = type === 'PAYMENT.CAPTURE.COMPLETED';
const failed = type === 'PAYMENT.CAPTURE.DENIED' || type === 'CHECKOUT.ORDER.DECLINED';

return [{
  json: {
    event_type: type,
    paypal_order_id: paypalOrderId,
    paid: paid,
    failed: failed,
    handled: Boolean(paypalOrderId) && (paid || failed)
  }
}];

const rows = $('Find Merchant Row').all();
const paid = $('read_PayPal_Event').first().json || {};
const order = $('load_Order_From_Event').first().json || {};

// Only a captured payment adds revenue.
if (!paid.paid) {
  return [];
}

let row = null;
for (const r of rows) {
  if (r.json && r.json.id) { row = r.json; break; }
}
if (!row) {
  return [{ json: { skipped: true, reason: 'No Baserow row matched slug ' + String(order.slug || '') } }];
}

// Any currency: keep a per-currency ledger so different currencies never get mixed.
let ledger = {};
try {
  if (row.revenue_ledger) ledger = JSON.parse(String(row.revenue_ledger));
} catch (e) { ledger = {}; }

const currency = String(order.currency || 'USD').toUpperCase();
const amount = Number(order.amount_usd || 0);
if (!ledger[currency]) ledger[currency] = 0;
ledger[currency] = Number((ledger[currency] + amount).toFixed(2));

// The merchant's revenue column is one comparable number, so it is kept in USD. An order paid in
// another currency is converted at the live rate first - a EUR order credited as if its figure
// were dollars overstates the merchant's takings, and a shilling figure would overstate them a
// hundredfold. If the rate cannot be fetched the run is left uncounted rather than guessed at.
let toUsd = 1;
if (currency !== 'USD') {
  toUsd = 0;
  try {
    const fx = await this.helpers.httpRequest({ method: 'GET', url: 'https://open.er-api.com/v6/latest/USD', json: true, timeout: 8000 });
    const rate = fx && fx.rates ? Number(fx.rates[currency]) : 0;
    if (rate > 0) toUsd = 1 / rate;
  } catch (e) { toUsd = 0; }
}
if (!(toUsd > 0) || !(amount > 0)) {
  return [{ json: { skipped: true, reason: 'Revenue not credited: no usable USD rate for ' + currency + ' amount ' + amount } }];
}
const amountUsd = Number((amount * toUsd).toFixed(2));

// Keep the plain revenue column meaningful too (insights reads it).
// Do NOT write revenue_ledger: that column does not exist in Baserow and an unknown
// field makes the whole PATCH fail, so revenue would never be saved.
const primary = Number(row.revenue || 0);
const newPrimary = Number((primary + amountUsd).toFixed(2));

return [{
  json: {
    id: row.id,
    revenue: newPrimary
  }
}];
